/**
 * Docs Page - Shows document files (PDF, DOC, DOCX, etc.)
 */

import React from 'react';
import { useFiles } from '../../hooks/useFiles';
import { filesService } from '../../services';
import FileItem from '../../components/FileItem/FileItem';

const Docs = () => {
  const { files, loading: filesLoading, downloadFile, refetch: refetchFiles } = useFiles(null);

  // Filter for document files
  const documentTypes = [
    'application/pdf',
    'application/msword',
    'application/vnd.openxmlformats-officedocument.wordprocessingml.document',
    'application/vnd.ms-excel',
    'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet',
    'text/plain',
    'text/rtf',
  ];

  const documentFiles = files.filter(file => {
    const mimeType = file.mime_type || file.mimeType || '';
    return documentTypes.some(type => mimeType.includes(type)) || 
           file.name?.toLowerCase().match(/\.(pdf|doc|docx|txt|rtf)$/);
  });

  const handleDownload = async (fileId) => {
    try {
      await downloadFile(fileId);
    } catch (error) {
      alert(`Failed to download: ${error.message}`);
    }
  };

  const handleDelete = async (fileId) => {
    if (window.confirm('Move this file to trash?')) {
      try {
        await filesService.deleteFile(fileId);
        refetchFiles();
      } catch (error) {
        alert(`Failed to delete: ${error.message}`);
      }
    }
  };

  if (filesLoading) {
    return (
      <div className="docs-page">
        <div className="loading-container">
          <div className="loading-spinner"></div>
          <p>Loading documents...</p>
        </div>
      </div>
    );
  }

  return (
    <div className="docs-page">
      {documentFiles.length === 0 ? (
        <div className="empty-state">
          <div className="empty-state-content">
            <div className="empty-illustration">
              <svg width="180" height="180" viewBox="0 0 200 200" fill="none" xmlns="http://www.w3.org/2000/svg">
                <defs>
                  <linearGradient id="docsGradient" x1="0%" y1="0%" x2="100%" y2="100%">
                    <stop offset="0%" style={{stopColor: '#4285F4', stopOpacity: 1}} />
                    <stop offset="100%" style={{stopColor: '#1a73e8', stopOpacity: 1}} />
                  </linearGradient>
                </defs>
                <rect x="60" y="40" width="80" height="120" rx="4" fill="url(#docsGradient)" opacity="0.9"/>
                <rect x="70" y="50" width="60" height="8" rx="2" fill="rgba(255,255,255,0.3)"/>
                <rect x="70" y="65" width="50" height="8" rx="2" fill="rgba(255,255,255,0.3)"/>
                <rect x="70" y="80" width="55" height="8" rx="2" fill="rgba(255,255,255,0.3)"/>
                <line x1="70" y1="100" x2="130" y2="100" stroke="rgba(255,255,255,0.3)" strokeWidth="2"/>
                <rect x="70" y="110" width="40" height="8" rx="2" fill="rgba(255,255,255,0.3)"/>
                <rect x="70" y="125" width="45" height="8" rx="2" fill="rgba(255,255,255,0.3)"/>
              </svg>
            </div>
            <p className="empty-hint">No documents found. Upload PDF, DOC, or DOCX files to see them here.</p>
          </div>
        </div>
      ) : (
        <div className="file-grid">
          <div className="file-grid-header">
            <div className="file-header-name">Name</div>
            <div className="file-header-meta">Size</div>
            <div className="file-header-actions"></div>
          </div>
          {documentFiles.map((file) => (
            <FileItem
              key={file.id}
              file={file}
              onDownload={handleDownload}
              onDelete={handleDelete}
            />
          ))}
        </div>
      )}
    </div>
  );
};

export default Docs;
